// Unidades disponibles para definir los rangos de un envase desechable.
const UNIDADES_ENVASE = [
  { id: "kg", label: "kilos", sufijo: "kg" },
  { id: "piezas", label: "piezas", sufijo: "pzas" },
  { id: "litros", label: "litros", sufijo: "L" },
];

// Migra envases guardados antes de que tuvieran "unidad" (usaban solo kgMin/kgMax).
const normalizarDesechable = (d) => ({
  ...d,
  unidad: d.unidad || "kg",
  rangoMin: d.rangoMin != null ? d.rangoMin : d.kgMin || 0,
  rangoMax: d.rangoMax != null ? d.rangoMax : d.kgMax != null ? d.kgMax : 999,
});

// Nombre para identificar una paellera: el que le puso el usuario, o si no
// tiene, su rango de kilos como respaldo.
const nombrePaellera = (t) => (t.nombre && t.nombre.trim() ? t.nombre.trim() : `Paellera ${t.rangoMin}-${t.rangoMax}kg`);

// Compara si un valor cae dentro de un rango [min, max], incluyendo AMBOS
// extremos ("de 5 a 7 kg" incluye 5, 6 y 7). Si dos rangos llegan a tocarse
// (ej. "de 2 a 4" y "de 4 a 6"), el valor del límite compartido cae en el
// primero que aparezca en la lista — no hay hueco ni doble conteo.
const enRango = (valor, min, max) => valor >= min && valor <= max;

// Calcula cuántos envases de cada tipo consume un pedido:
// - Paellas sin paellera: el envase cuyo rango en KILOS incluya los kilos de la paella.
// - Platillos con empaque "pieza": un envase por cada unidad pedida.
// - Platillos con empaque "rango": el envase cuyo rango en PIEZAS incluya el total pedido
//   (ej. 6 piezas → contenedor chico, 7 a 24 → contenedor grande).
const calcularConsumo = (items, desechables, extrasCatalogo) => {
  const consumo = {};
  const envases = (desechables || []).map(normalizarDesechable);
  (items || []).forEach((it) => {
    if (it.tipo === "paella" && !it.enPaellera) {
      const tier = envases.find((d) => d.unidad === "kg" && enRango(it.kg, d.rangoMin, d.rangoMax));
      if (tier) consumo[tier.id] = (consumo[tier.id] || 0) + 1;
    }
    // Platillos con empaque vinculado (ej. alioli en su envase, croquetas
    // en el contenedor que corresponda según cuántas piezas se pidieron).
    if (it.tipo === "extra") {
      const cat = (extrasCatalogo || []).find((e) => e.id === it.extraId);
      if (!cat || !cat.empaqueTipo || cat.empaqueTipo === "ninguno") return;
      if (cat.empaqueTipo === "pieza" && cat.empaqueEnvaseId) {
        consumo[cat.empaqueEnvaseId] = (consumo[cat.empaqueEnvaseId] || 0) + Math.ceil(it.cantidad);
      } else if (cat.empaqueTipo === "rango") {
        const totalPiezas = it.piezasPorUnidad > 0 ? it.cantidad * it.piezasPorUnidad : it.cantidad;
        const tier = envases.find((d) => d.unidad === "piezas" && enRango(totalPiezas, d.rangoMin, d.rangoMax));
        if (tier) consumo[tier.id] = (consumo[tier.id] || 0) + 1;
      }
    }
  });
  return consumo;
};

// direccion: "consumir" descuenta del stock, "restaurar" lo regresa (nunca baja de 0)
const ajustarStock = (desechables, consumo, direccion) =>
  (desechables || []).map((d) => {
    const cantidad = consumo[d.id] || 0;
    if (cantidad === 0) return d;
    const delta = direccion === "consumir" ? -cantidad : cantidad;
    return { ...d, stock: Math.max(0, Math.round((d.stock + delta) * 100) / 100) };
  });

// ---- Unidades de medida para ingredientes ----
// La app convierte entre unidades de la misma familia (peso: g/kg, volumen: ml/l,
// piezas: pza) para descontar en "presentaciones" (bolsas, cajas...) aunque el
// uso por kilo de paella esté en gramos o piezas.
const UNIDADES_MEDIDA = [
  { id: "g", label: "gramos", familia: "peso", factor: 1 },
  { id: "kg", label: "kilos", familia: "peso", factor: 1000 },
  { id: "ml", label: "mililitros", familia: "volumen", factor: 1 },
  { id: "l", label: "litros", familia: "volumen", factor: 1000 },
  { id: "pza", label: "piezas", familia: "piezas", factor: 1 },
];
const UNIDAD_INFO = Object.fromEntries(UNIDADES_MEDIDA.map((u) => [u.id, u]));
const PRESENTACIONES = ["bolsa", "caja", "paquete", "costal", "botella", "lata", "frasco", "pieza"];

// Migra ingredientes del modelo viejo (solo unidad/stock) al nuevo con presentación.
const normalizarIngrediente = (ing) => {
  if (ing.presentacionCantidad != null) return ing;
  const u = UNIDAD_INFO[ing.unidad] ? ing.unidad : "pza";
  return {
    ...ing,
    presentacionNombre: "paquete",
    presentacionCantidad: 1,
    presentacionUnidad: u,
    usoUnidad: u,
    porKg: ing.porKg || {},
  };
};

// Consumo de ingredientes EN PRESENTACIONES (bolsas/cajas) según la receta:
// (uso por kg × kilos del pedido, convertido a la unidad base) ÷ contenido de la presentación.
const calcularConsumoIngredientes = (items, ingredientes) => {
  const consumo = {};
  items.forEach((it) => {
    if (it.tipo !== "paella") return;
    (ingredientes || []).forEach((raw) => {
      const ing = normalizarIngrediente(raw);
      const porKg = (ing.porKg || {})[it.paellaId] || 0;
      if (porKg <= 0) return;
      const fUso = (UNIDAD_INFO[ing.usoUnidad] || { factor: 1 }).factor;
      const fPres = (UNIDAD_INFO[ing.presentacionUnidad] || { factor: 1 }).factor;
      const contenido = (ing.presentacionCantidad || 1) * fPres;
      if (contenido <= 0) return;
      consumo[ing.id] = (consumo[ing.id] || 0) + (porKg * it.kg * fUso) / contenido;
    });
  });
  return consumo;
};

// Resumen de producción de un conjunto de pedidos (normalmente los de un
// mismo día): cuántos kilos de cada paella, cuántas piezas de cada platillo
// (cada uno por separado, ej. "Croquetas de Bacalao" y "Croquetas de Jamón"
// no se juntan), y cuánto de cada ingrediente con receta (ej. camarón) hay
// que preparar. A diferencia de calcularConsumoIngredientes (que da "bolsas"
// a descontar del stock), aquí queremos la cantidad cruda en la unidad de
// uso del ingrediente (piezas, gramos...), que es lo que se necesita para
// pelar o sacar del congelador.
const produccionDelDia = (pedidosDelDia, config) => {
  const paellasKg = {}; // paellaId -> kg total
  const platillos = {}; // extraId -> cantidad total (piezas si aplica, si no unidades)
  const ingredientesUso = {}; // ingredienteId -> cantidad en su usoUnidad
  const sueltasPorPaella = {}; // paellaId -> kg de PAELLA_SUELTA_MAX_KG o menos: no cabe en ninguna paellera

  pedidosDelDia.forEach((p) => {
    (p.items || []).forEach((it) => {
      if (it.tipo === "paella") {
        paellasKg[it.paellaId] = (paellasKg[it.paellaId] || 0) + it.kg;
        if (it.kg <= PAELLA_SUELTA_MAX_KG) sueltasPorPaella[it.paellaId] = (sueltasPorPaella[it.paellaId] || 0) + it.kg;
      } else if (it.tipo === "extra") {
        // Cantidad convertida a piezas cuando aplica (ej. 4 órdenes de
        // "ración de 6" = 24 piezas): es lo que hay que sacar del
        // congelador para descongelar. Cada platillo/sabor por separado.
        // Se usan las "piezas por orden" ACTUALES de Ajustes (no el valor
        // que el pedido guardó al crearse): si ese número se definió o
        // cambió después de que ya existían pedidos, esos pedidos viejos
        // no se cuentan de menos.
        const catalogo = (config.extras || []).find((e) => e.id === it.extraId);
        const piezasPorUnidad = catalogo ? catalogo.piezasPorUnidad || 0 : it.piezasPorUnidad || 0;
        const cant = piezasPorUnidad > 0 ? it.cantidad * piezasPorUnidad : it.cantidad;
        platillos[it.extraId] = (platillos[it.extraId] || 0) + cant;
      }
    });
  });

  // Solo ingredientes marcados explícitamente (ej. camarón, que se pela con
  // anticipación) — el resto de la receta no hace falta anunciarlo aquí.
  (config.ingredientes || []).filter((raw) => raw.avisarProduccion).forEach((raw) => {
    const ing = normalizarIngrediente(raw);
    let total = 0;
    Object.entries(paellasKg).forEach(([paellaId, kg]) => {
      const porKg = (ing.porKg || {})[paellaId] || 0;
      total += porKg * kg;
    });
    if (total > 0) ingredientesUso[ing.id] = total;
  });

  return { paellasKg, platillos, ingredientesUso, sueltasPorPaella };
};

// Paelleras (los recipientes grandes que se prestan al cliente) necesarias
// un día, según el rango de kilos de cada paella configurado en Ajustes →
// Inventario. Las paellas de PAELLA_SUELTA_MAX_KG o menos no caben en
// ninguna paellera y se cuentan aparte como "sueltas".
const PAELLA_SUELTA_MAX_KG = 2;
const paellerasDelDia = (pedidosDelDia, paelleras) => {
  const conteo = {}; // paelleraId -> cuántas se necesitan
  pedidosDelDia.forEach((p) => {
    (p.items || []).forEach((it) => {
      if (it.tipo !== "paella" || it.kg <= PAELLA_SUELTA_MAX_KG) return;
      const tier = (paelleras || []).find((t) => enRango(it.kg, t.rangoMin, t.rangoMax));
      if (tier) conteo[tier.id] = (conteo[tier.id] || 0) + 1;
    });
  });
  return conteo;
};

// Capacidad de cocina: cuántas paellas (líneas, no kilos) hay agendadas el
// mismo día dentro de ±30 min de una hora, sin contar el pedido que se está
// guardando (para no contarlo dos veces al editar).
const MAX_PAELLAS_POR_FRANJA = 5;
const minutosDeHora = (hora) => {
  const [h, m] = (hora || "00:00").split(":").map(Number);
  return h * 60 + m;
};
const contarPaellasEnFranja = (pedidos, fecha, hora, excluirId) => {
  const centro = minutosDeHora(hora);
  let total = 0;
  pedidos.forEach((p) => {
    if (p.id === excluirId || p.fecha !== fecha) return;
    // Los pedidos ya entregados no compiten por tiempo de cocina: no cuentan
    // para la alerta de "muchas paellas a la vez".
    if ((p.estado || "pendiente") === "entregado") return;
    if (Math.abs(minutosDeHora(p.hora) - centro) > 30) return;
    total += p.items.filter((it) => it.tipo === "paella").length;
  });
  return total;
};

// Compatibilidad con pedidos guardados antes de que la paellera fuera por platillo:
// si el pedido viejo tenía paellera a nivel general, se aplica a sus paellas.
// Asigna folio consecutivo a los registros que aún no lo tengan (datos viejos),
// respetando el orden de creación para que los folios queden cronológicos.
const asignarFolios = (lista) => {
  let max = lista.reduce((m, x) => Math.max(m, x.folio || 0), 0);
  const sinFolio = lista.filter((x) => !x.folio).sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
  const mapa = new Map(sinFolio.map((x) => [x.id, ++max]));
  return lista.map((x) => (x.folio ? x : { ...x, folio: mapa.get(x.id) }));
};

const migrarPedido = (p) => {
  const items = (p.items || []).map((it) => {
    if (it.tipo !== "paella") return it;
    return {
      ...it,
      enPaellera: it.enPaellera !== undefined ? it.enPaellera : !!p.paellera,
      paelleraDevuelta: it.paelleraDevuelta !== undefined ? it.paelleraDevuelta : !!p.paelleraDevuelta,
    };
  });
  const { paellera, paelleraDevuelta, ...resto } = p;
  // Migra el pago viejo (un monto + un método) a la lista de abonos, que
  // permite mezclar formas de pago (ej. anticipo por transferencia, resto en efectivo).
  const abonos = p.abonos || (p.pagado > 0 ? [{ id: uid(), monto: p.pagado, metodo: p.metodoPago || "efectivo" }] : []);
  return { ...resto, items, estado: p.estado || "pendiente", abonos };
};

const sumaAbonos = (abonos) => (abonos || []).reduce((a, x) => a + (parseFloat(x.monto) || 0), 0);

/* ---------------------------------------------------------------------- */
/*  Componentes pequeños de presentación                                  */
/* ---------------------------------------------------------------------- */

// Input numérico con memoria propia: se puede borrar y escribir libremente
// mientras se edita, y solo se valida/redondea al salir del campo.
function NumberField({ value, onChange, min, className, disabled }) {
  const [text, setText] = useState(String(value));
  useEffect(() => { setText(String(value)); }, [value]);

  const commit = () => {
    const v = parseFloat(text);
    const limpio = Number.isNaN(v) ? (min != null ? min : 0) : (min != null ? Math.max(min, v) : v);
    onChange(limpio);
    setText(String(limpio));
  };

  return (
    <input
      type="text"
      inputMode="decimal"
      className={className}
      value={text}
      disabled={disabled}
      onFocus={(e) => e.target.select()}
      onChange={(e) => setText(e.target.value)}
      onBlur={commit}
      onKeyDown={(e) => { if (e.key === "Enter") e.target.blur(); }}
    />
  );
}

// Igual que NumberField pero para texto: guarda al salir del campo y no en
// cada tecla, para no escribir en la nube con cada letra.
function TextoField({ value, onChange, className, placeholder, list }) {
  const [text, setText] = useState(value || "");
  useEffect(() => { setText(value || ""); }, [value]);
  return (
    <input
      type="text"
      className={className}
      placeholder={placeholder}
      list={list}
      value={text}
      onChange={(e) => setText(e.target.value)}
      onBlur={() => { if (text !== (value || "")) onChange(text); }}
      onKeyDown={(e) => { if (e.key === "Enter") e.target.blur(); }}
    />
  );
}

function Stepper({ value, onChange, min = 1, step = 1 }) {
  return (
    <div className="flex items-center gap-2">
      <button type="button" className="af-stepper-btn" onClick={() => onChange(Math.max(min, +(value - step).toFixed(2)))}>
        <Minus size={14} />
      </button>
      <NumberField value={value} min={min} className="af-stepper-input" onChange={onChange} />
      <button type="button" className="af-stepper-btn" onClick={() => onChange(+(value + step).toFixed(2))}>
        <Plus size={14} />
      </button>
    </div>
  );
}

// Campo para la ubicación: se puede escribir/pegar a mano, o con el botón
// se toma directo del portapapeles (para cuando copian el link desde WhatsApp).
function UbicacionField({ value, onChange, placeholder }) {
  const pegar = async () => {
    try {
      const texto = await navigator.clipboard.readText();
      if (texto) onChange(texto.trim());
    } catch (e) {
      // El navegador puede negar el permiso de portapapeles; no pasa nada,
      // igual se puede pegar a mano con Cmd/Ctrl+V.
    }
  };
  return (
    <div className="af-ubic-row">
      <input
        className="af-input"
        value={value}
        placeholder={placeholder || "Pega aquí el link de ubicación"}
        onChange={(e) => onChange(e.target.value)}
      />
      <button type="button" className="af-paste-btn" onClick={pegar} title="Pegar desde el portapapeles">
        <ClipboardPaste size={16} />
      </button>
    </div>
  );
}

function Badge({ estado }) {
  const map = {
    pagado: { label: "Pagado", cls: "af-badge af-badge-olive" },
    parcial: { label: "Parcial", cls: "af-badge af-badge-gold" },
    pendiente: { label: "Pendiente", cls: "af-badge af-badge-wine" },
  };
  const cfg = map[estado] || map.pendiente;
  return <span className={cfg.cls}>{cfg.label}</span>;
}

function StatPill({ label, value, warn }) {
  return (
    <div className="af-stat-pill">
      <div className={"af-stat-value" + (warn ? " af-stat-warn" : "")}>{value}</div>
      <div className="af-stat-label">{label}</div>
    </div>
  );
}

function EstadoPedidoSelect({ estado, onChange }) {
  return (
    <select
      className={"af-estado-select af-estado-" + estado}
      value={estado}
      onClick={(e) => e.stopPropagation()}
      onChange={(e) => onChange(e.target.value)}
    >
      {ESTADOS_PEDIDO.map((e) => (
        <option key={e.id} value={e.id}>{e.label}</option>
      ))}
    </select>
  );
}

function OrderCard({ pedido, onClick, showFecha, onCambiarEstado, onEnviarAvisoWhatsApp, avisoPendiente }) {
  const itemsPaellera = pedido.items.filter((it) => it.tipo === "paella" && it.enPaellera);
  const hayPaellera = itemsPaellera.length > 0;
  const todasDevueltas = hayPaellera && itemsPaellera.every((it) => it.paelleraDevuelta);
  const estado = pedido.estado || "pendiente";
  // En celular (sobre todo iOS), abrir WhatsApp automático desde el onChange
  // de un <select> casi nunca funciona: el navegador no lo cuenta como un
  // toque directo del usuario y bloquea la ventana en silencio. Por eso, en
  // vez de intentarlo solo, mostramos un botón para que el envío salga de un
  // toque real. avisoPendiente ("avisado" | "entregado" | undefined) llega
  // como prop desde App — se guarda ahí y no aquí como estado local porque al
  // marcar "Entregado" la tarjeta salta de la lista de pendientes a la de
  // entregados (listas distintas) y React la desmonta y monta de nuevo,
  // perdiendo cualquier estado propio antes de que el botón llegue a mostrarse.
  return (
    <div className="af-card af-ticket p-4 mb-3 cursor-pointer" onClick={onClick}>
      <div className="flex items-start justify-between gap-2">
        <div>
          <div className="flex items-baseline gap-2 flex-wrap">
            <span className="af-hora">{fmtHora12(pedido.hora)}</span>
            <span className="af-cliente-nombre">{pedido.clienteNombre}</span>
            {pedido.folio && <span className="af-folio-tag">{fmtFolio(pedido.folio, "#")}</span>}
            {/* Se avisa a la vista que este pedido lo apuntó el asistente y no
                una persona, para que nadie lo dé por confirmado de más ni se
                confunda al verlo aparecer solo. */}
            {esPedidoDeIA(pedido) && (
              <span className="af-chip af-chip-ia" title="Lo apuntó el asistente de WhatsApp; conviene confirmarlo con el cliente">
                <MessageCircle size={11} /> Por WhatsApp
              </span>
            )}
          </div>
          {showFecha && <div className="af-fecha-sub">{fmtDateHuman(pedido.fecha)}</div>}
        </div>
        {onCambiarEstado ? (
          <EstadoPedidoSelect estado={estado} onChange={(v) => onCambiarEstado(pedido.id, v)} />
        ) : (
          <span className={"af-badge af-estado-badge af-estado-" + estado}>{ESTADO_LABEL[estado]}</span>
        )}
      </div>

      {avisoPendiente && onEnviarAvisoWhatsApp && pedido.clienteTelefono && (
        <button
          className="af-btn-wa w-full mb-2"
          onClick={(e) => { e.stopPropagation(); onEnviarAvisoWhatsApp(pedido); }}
        >
          <MessageCircle size={15} className="inline mr-1" />
          {avisoPendiente === "entregado" ? "Enviar aviso de entrega" : "Enviar aviso por WhatsApp"}
        </button>
      )}

      <div className="af-tear" />

      <div className="flex items-center gap-2 flex-wrap mb-2">
        {pedido.entrega ? (
          <span className="af-chip af-chip-domicilio">
            <Truck size={12} /> A domicilio
          </span>
        ) : (
          <span className="af-chip af-chip-neutral">
            <Store size={12} /> Recoger
          </span>
        )}
        {pedido.entrega && pedido.ubicacion && (
          <a
            href={pedido.ubicacion}
            target="_blank"
            rel="noopener noreferrer"
            className="af-chip af-chip-gold"
            onClick={(e) => e.stopPropagation()}
          >
            <MapPin size={12} /> Abrir ubicación
          </a>
        )}
        {hayPaellera && (
          <span className={"af-chip " + (todasDevueltas ? "af-chip-olive" : "af-chip-gold")}>
            <ChefHat size={12} /> {todasDevueltas ? "Paellera devuelta" : itemsPaellera.length > 1 ? `${itemsPaellera.length} paelleras` : "Paellera"}
          </span>
        )}
      </div>

      <ul className="af-resumen-lista">
        {pedido.items.map((it) => (
          <li key={it.id}>
            {it.tipo === "paella"
              ? `${it.paellaNombre} — ${fmtKg(it.kg)}${resumenExtras(it)}${it.enPaellera ? " · paellera" : ""}`
              : `${it.nombre} ${it.unidad === "kg" ? "— " + fmtKg(it.cantidad) : "× " + it.cantidad}`}
            {it.nota && (
              <div className="af-item-nota">
                <StickyNote size={12} className="inline mr-1" />{it.nota}
              </div>
            )}
          </li>
        ))}
        {pedido.envio > 0 && <li>Envío a domicilio — {money(pedido.envio)}</li>}
        {pedido.iva && <li>IVA (16%) incluido</li>}
      </ul>

      <div className="flex items-center justify-between mt-2">
        <span className="af-total">{money(pedido.total)}</span>
        {pedido.saldo > 0 && <span className="af-saldo">Saldo {money(pedido.saldo)}</span>}
      </div>
    </div>
  );
}

/* ------------------------- Bandeja de WhatsApp ------------------------- */
// El bot solo apunta pedidos rutinarios. Todo lo demás — dudas raras, quejas,
// eventos, o cuando el cliente pide hablar con una persona — llega aquí para
// que Pepe conteste él mismo, que es lo que la gente busca del negocio.

function MensajesView({ conversaciones, onAbrir, abierta, mensajes, cargandoChat, onEnviar, onVolver }) {
  const [texto, setTexto] = useState("");
  const [enviando, setEnviando] = useState(false);
  const finRef = useRef(null);

  // Al abrir un chat o al llegar un mensaje, se baja hasta lo último.
  useEffect(() => {
    if (finRef.current) finRef.current.scrollIntoView({ block: "end" });
  }, [mensajes, abierta]);

  const enviar = async () => {
    const limpio = texto.trim();
    if (!limpio || enviando) return;
    setEnviando(true);
    const ok = await onEnviar(abierta.telefono, limpio);
    setEnviando(false);
    if (ok) setTexto("");
  };

  if (abierta) {
    const nombre = abierta.nombre || fmtTel(abierta.telefono);
    return (
      <div className="af-chat">
        <div className="af-chat-head">
          <button className="af-icon-btn" onClick={onVolver} title="Volver a la lista">
            <ArrowLeft size={18} />
          </button>
          <div className="af-chat-head-txt">
            <div className="af-chat-head-nombre">{nombre}</div>
            <div className="af-chat-head-tel">{fmtTel(abierta.telefono)}</div>
          </div>
          <a className="af-icon-btn" href={`tel:+${abierta.telefono}`} title="Marcarle">
            <MessageCircle size={18} />
          </a>
        </div>

        {abierta.motivo_pepe && (
          <div className="af-chat-motivo">
            <AlertTriangle size={14} /> {abierta.motivo_pepe}
          </div>
        )}

        <div className="af-chat-cuerpo">
          {cargandoChat ? (
            <div className="af-chat-vacio">Cargando la conversación…</div>
          ) : mensajes.length === 0 ? (
            <div className="af-chat-vacio">Todavía no hay mensajes en este chat.</div>
          ) : (
            mensajes.map((m) => (
              <div key={m.id} className={"af-burbuja af-burbuja-" + m.de}>
                {m.de === "bot" && <div className="af-burbuja-quien">Contestó el asistente</div>}
                <div className="af-burbuja-txt">{m.texto}</div>
                <div className="af-burbuja-hora">{fmtHoraCorta(m.creado_at)}</div>
              </div>
            ))
          )}
          <div ref={finRef} />
        </div>

        <div className="af-chat-pie">
          <textarea
            className="af-chat-input"
            rows={1}
            placeholder="Escríbele…"
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); enviar(); }
            }}
          />
          <button className="af-chat-enviar" onClick={enviar} disabled={!texto.trim() || enviando}>
            {enviando ? "…" : <ArrowRightCircle size={20} />}
          </button>
        </div>
      </div>
    );
  }

  if (!conversaciones.length) {
    return (
      <EmptyState
        icon={<MessageCircle size={30} />}
        title="Sin conversaciones todavía"
        subtitle="Aquí aparecerán los clientes que escriban por WhatsApp."
      />
    );
  }

  return (
    <div>
      {conversaciones.map((c) => (
        <button key={c.telefono} className={"af-conv" + (c.necesita_pepe ? " pendiente" : "")} onClick={() => onAbrir(c)}>
          <div className="af-conv-top">
            <span className="af-conv-nombre">{c.nombre || fmtTel(c.telefono)}</span>
            <span className="af-conv-hora">{fmtHoraCorta(c.ultimo_at)}</span>
          </div>
          <div className="af-conv-txt">{c.ultimo_texto}</div>
          {c.necesita_pepe && (
            <div className="af-conv-aviso">
              <AlertTriangle size={13} /> {c.motivo_pepe || "Te toca contestar a ti"}
            </div>
          )}
        </button>
      ))}
    </div>
  );
}

// Campo de texto con sugerencias propias.
//
// Sustituye al <datalist> del navegador: en Safari de iPhone y iPad ese
// desplegable falla seguido — a veces sale vacío y no deja elegir nada.
// Este se dibuja con HTML normal, así que se comporta igual en todos lados.
function CampoConSugerencias({ value, onChange, sugerencias = [], className = "af-input", placeholder, onBlur }) {
  const [abierto, setAbierto] = useState(false);
  const [resaltado, setResaltado] = useState(-1);
  const contenedorRef = useRef(null);

  const escrito = (value || "").trim().toLowerCase();
  const opciones = sugerencias
    .filter((s) => s && (!escrito || s.toLowerCase().includes(escrito)) && s.toLowerCase() !== escrito)
    .slice(0, 8);

  // Al tocar fuera se cierra, igual que un desplegable de verdad.
  useEffect(() => {
    if (!abierto) return;
    const alTocarFuera = (e) => {
      if (contenedorRef.current && !contenedorRef.current.contains(e.target)) setAbierto(false);
    };
    document.addEventListener("mousedown", alTocarFuera);
    document.addEventListener("touchstart", alTocarFuera);
    return () => {
      document.removeEventListener("mousedown", alTocarFuera);
      document.removeEventListener("touchstart", alTocarFuera);
    };
  }, [abierto]);

  const elegir = (texto) => {
    onChange(texto);
    setAbierto(false);
    setResaltado(-1);
  };

  return (
    <div className="af-sug-wrap" ref={contenedorRef}>
      <input
        className={className}
        value={value || ""}
        placeholder={placeholder}
        onChange={(e) => { onChange(e.target.value); setAbierto(true); setResaltado(-1); }}
        onFocus={() => setAbierto(true)}
        onBlur={onBlur}
        onKeyDown={(e) => {
          if (!abierto || !opciones.length) return;
          if (e.key === "ArrowDown") { e.preventDefault(); setResaltado((i) => (i + 1) % opciones.length); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setResaltado((i) => (i <= 0 ? opciones.length : i) - 1); }
          else if (e.key === "Enter" && resaltado >= 0) { e.preventDefault(); elegir(opciones[resaltado]); }
          else if (e.key === "Escape") setAbierto(false);
        }}
      />
      {abierto && opciones.length > 0 && (
        <div className="af-sug-lista">
          {opciones.map((s, i) => (
            <button
              key={s}
              type="button"
              className={"af-sug-item" + (i === resaltado ? " activo" : "")}
              // onMouseDown y no onClick: si no, el blur del input cierra la
              // lista antes de que el clic llegue a registrarse.
              onMouseDown={(e) => { e.preventDefault(); elegir(s); }}
            >
              {s}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

